use kni_core::{capture::capture_png,capture_fit::fit_captured,cubic_fit::FitPolicy,reference_slice::Span};
fn main(){let png=std::fs::read(std::env::args().nth(1).unwrap()).unwrap();let mc=capture_png(&png,0.5).unwrap();let min=mc.rings.iter().flat_map(|r|r.points.iter()).map(|p|p.y).fold(f64::INFINITY,f64::min);let max=mc.rings.iter().flat_map(|r|r.points.iter()).map(|p|p.y).fold(f64::NEG_INFINITY,f64::max);let scale=700./(max-min);let (rings,_,_,_)=fit_captured(&mc.rings,scale,&FitPolicy{squared_error:0.1,max_refits:6});println!("capture_y={min:.17},{max:.17} scale={scale:.17}");let r=&rings[2];println!("start={:?} span0={:?}",r.start,r.spans[0]);let mut all=Vec::new();for r in &rings{all.push(r.start);for s in &r.spans{match s{Span::Line{end}=>all.push(*end),Span::Cubic{control_one,control_two,end}=>all.extend([*control_one,*control_two,*end])}}}println!("bounds={:?}",all.iter().fold((f64::INFINITY,f64::INFINITY,f64::NEG_INFINITY,f64::NEG_INFINITY),|b,p|(b.0.min(p.x),b.1.min(p.y),b.2.max(p.x),b.3.max(p.y))));}
